import { describe, it } from "vitest";

// Chosen error contract: invalid scenarios make scenario evaluation throw an Error;
// the CLI translates that into a non-zero exit, a message on stderr, and no stdout results.

describe("quote premium", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("plain sword, newcomer's first quote -> premium 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("plain amulet, newcomer's first quote -> premium 71 G (60 + 6 + 5)");
  it.todo("plain staff, newcomer's first quote -> premium 93 G (80 + 8 + 5)");
  it.todo("plain potion, newcomer's first quote -> premium 49 G (40 + 4 + 5)");
});

describe("component base premium", () => {
  it.todo("2 runes -> 50 G base premium");
  it.todo("3 runes -> 60 G base premium (block applies)");
  it.todo("4 runes -> 100 G base premium (block requires exactly 3)");
  it.todo("7 runes -> 175 G base premium");
  it.todo("2 runes + 1 moonstone -> 75 G base premium (alike means same type; no block)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two separate blocks)");
});

describe("premium modifiers", () => {
  it.todo("newcomer with cursed steel sword, enchantment 3 -> premium 165 G");
  it.todo("sword with enchantment 4, not cursed -> no high-enchantment surcharge -> premium 115 G");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge -> premium 145 G");
  it.todo("cursed sword with enchantment 5 -> both surcharges -> premium 195 G");
  it.todo("cursed sword + plain amulet -> curse surcharge only on sword (210 G) + 16 first insurance + 5 fee -> premium 231 G");
  it.todo("customer with exactly 2 years -> loyalty discount -> plain sword premium 95 G");
  it.todo("customer with 1 year -> no loyalty discount -> plain sword premium 115 G");
  it.todo("newcomer's second quote -> follow-up discount -> plain sword premium 100 G");
  it.todo("3-year customer's second quote of cursed sword, enchantment 7 -> premium 160 G (first insurance still applies)");
  it.todo("premium computing to 197.5 G -> rounded up to 198 G");
  it.todo("quote with unknown item type (broomstick) -> throws Error");
});

describe("claim payout", () => {
  it.todo("regular steel sword enchantment 3, damage 500 -> payout 400 G, remaining cap 1600 G");
  it.todo("rune (250 G), damage 200 -> payout 100 G, remaining cap 400 G");
  it.todo("moonstone (250 G), damage 200 -> payout 100 G, remaining cap 400 G");
  it.todo("amulet (600 G), damage 200 -> payout 100 G, remaining cap 1100 G");
  it.todo("staff (800 G), damage 200 -> payout 100 G, remaining cap 1500 G");
  it.todo("potion (400 G), damage 200 -> payout 100 G, remaining cap 700 G");
  it.todo("dragon-material sword exactly enchantment 8, damage 1000 -> payout 400 G");
  it.todo("dragon-material sword enchantment 9, damage 1000 -> payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword enchantment 5, damage 800 -> payout 700 G");
  it.todo("steel sword enchantment 9, damage 1000 -> payout 400 G");
  it.todo("steel sword enchantment 9, damage 901 -> 350.5 rounded down to payout 350 G");
  it.todo("sword + amulet damaged 500 and 300 -> deductible per item -> payout 600 G, remaining cap 2600 G (cap 3200)");
  it.todo("two swords both damaged 500 -> payout 800 G, remaining cap 3200 G (cap 4000)");
  it.todo("cursed sword damaged 500 -> remaining cap 1600 G (cap 2000 from unmodified insurance value)");
  it.todo("sword + 3 runes, sword damaged 500 -> remaining cap 3100 G (insurance sum 1750, cap 3500)");
  it.todo("two successive 1500 G claims on a sword -> payouts 1400/600 G, remaining caps 600/0 G");
  it.todo("two sword damages but one sword insured -> throws Error (whole claim rejected)");
  it.todo("amulet damage when only a sword is insured -> throws Error");
  it.todo("damage with unknown item type -> throws Error");
  it.todo("damage amount -200 -> throws Error");
});

