export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

const PROCESSING_FEE = 5;

export function runScenario(scenario: Scenario): QuoteResult[] {
  return scenario.steps.map(() => ({ premium: PROCESSING_FEE }));
}
EOF
