import { openPolicy, settleClaim, type Policy } from "./claims.js";
import { quotePremium } from "./premium.js";

export { policyBasePremium } from "./premium.js";

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export interface Scenario {
  customer: Customer;
  steps: (QuoteStep | ClaimStep)[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export function runScenario(scenario: Scenario): (QuoteResult | ClaimResult)[] {
  const policies = new Map<number, Policy>();
  return scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      const previousContracts = policies.size;
      policies.set(index, openPolicy(step.items));
      return { premium: quotePremium(step.items, scenario.customer, previousContracts) };
    }
    return settleClaim(policies.get(step.policy) ?? openPolicy([]), step.incident.damages);
  });
}
import { insuranceValue } from "./catalogue.js";
import type { ClaimResult, Damage, Item } from "./claimOffice.js";

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;
const PERCENT = 100;
const HIGH_ENCHANTMENT_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;

function policyCap(insured: Item[]): number {
  const insuranceSum = insured.reduce((sum, item) => sum + insuranceValue(item), 0);
  return insuranceSum * CAP_FACTOR;
}

function reimbursementPercent(item: Item): number {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT : PERCENT;
}

interface CoveredDamage {
  damage: Damage;
  item: Item;
}

function damagePayout({ damage, item }: CoveredDamage): number {
  return (damage.amount * reimbursementPercent(item)) / PERCENT - DEDUCTIBLE;
}

function assertValidDamageAmount(damage: Damage): void {
  if (damage.amount < 0) {
    throw new Error(`Damage amount must not be negative: ${damage.amount}`);
  }
}

function matchCoveredDamages(insured: Item[], damages: Damage[]): CoveredDamage[] {
  const undamaged = [...insured];
  return damages.map((damage) => {
    const index = undamaged.findIndex((item) => item.type === damage.itemType);
    if (index === -1) {
      throw new Error(`Damaged ${damage.itemType} is not covered by the policy`);
    }
    return { damage, item: undamaged.splice(index, 1)[0] };
  });
}

function roundPayoutInMhpcoFavor(payout: number): number {
  return Math.floor(payout);
}

export interface Policy {
  items: Item[];
  remainingCap: number;
}

export function openPolicy(items: Item[]): Policy {
  return { items, remainingCap: policyCap(items) };
}

export function settleClaim(policy: Policy, damages: Damage[]): ClaimResult {
  damages.forEach(assertValidDamageAmount);
  const coveredDamages = matchCoveredDamages(policy.items, damages);
  const desiredPayout = roundPayoutInMhpcoFavor(
    coveredDamages.reduce((sum, coveredDamage) => sum + damagePayout(coveredDamage), 0),
  );
  const payout = Math.min(desiredPayout, policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}
import { COMPONENT, COMPONENT_TYPES, isComponent, mainItemEntry } from "./catalogue.js";
import type { Customer, Item } from "./claimOffice.js";

const PROCESSING_FEE = 5;
const PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_DISCOUNT_PERCENT = 15;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_LEVEL = 5;
function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function riskSurchargePercent(item: Item): number {
  const curse = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const highEnchantment = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return curse + highEnchantment;
}

function itemSurcharges(items: Item[]): number {
  return items
    .filter((item) => !isComponent(item))
    .reduce((sum, item) => sum + (mainItemBasePremium(item) * riskSurchargePercent(item)) / PERCENT, 0);
}

function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function isFollowUpContract(previousContracts: number): boolean {
  return previousContracts > 0;
}

function policyModifierPercent(customer: Customer, previousContracts: number): number {
  const loyalty = isLongStandingCustomer(customer) ? -LOYALTY_DISCOUNT_PERCENT : 0;
  const followUp = isFollowUpContract(previousContracts) ? -FOLLOW_UP_DISCOUNT_PERCENT : 0;
  return FIRST_INSURANCE_SURCHARGE_PERCENT + loyalty + followUp;
}

function roundPremiumInMhpcoFavor(premium: number): number {
  return Math.ceil(premium);
}

export function quotePremium(items: Item[], customer: Customer, previousContracts: number): number {
  const basePremium = policyBasePremium(items);
  const policyModifier = (basePremium * policyModifierPercent(customer, previousContracts)) / PERCENT;
  return roundPremiumInMhpcoFavor(basePremium + itemSurcharges(items) + policyModifier + PROCESSING_FEE);
}

